/// <summary>
/// Extension for journal check post to update the integration status and line count
/// </summary>
[ExtensionOf(classStr(InventJournalCheckPost_Movement))]
final class METInventJournalCheckPost_Movement_Extension
{
}

Method.Source:
/// <summary>
///    Validates the inventory journal.
/// </summary>
/// <param name="_journalTransList">
///    A list of inventory journal lines.
/// </param>
/// <returns>
///    true if the journal is valid; otherwise, false.
/// </returns>
protected boolean checkJournal(JournalTransList _journalTransList)
{
    boolean isJournalValid;

    isJournalValid = next checkJournal(_journalTransList);

    if (isJournalValid)
    {
        if (journalTableData.journalTable() is InventJournalTable)
        {
            InventJournalTable::updateMETLineCountAndResetIntStatusIfvalidCountingJournal(journalTableData.journalTable());
        }
    }
    return isJournalValid;
}
